// Trace capture: drives the real host through its public interface and writes
// one NDJSON window per step to spec/traces/. Run: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, 'traces');

const WORKERS = ['worker0', 'worker1'];
const ACTIONS = ['START', 'CANCEL', 'WORK_DONE', 'WORK_FAILED', 'DELIVER_ASSIGN', 'DELIVER_ABORT', 'DELIVER_REPORT'];

function find(msgs: Message[], pred: (m: Message) => boolean): Message | undefined {
  const hits = msgs.filter(pred);
  if (hits.length > 1) throw new Error('two in-flight messages of one kind: ' + JSON.stringify(hits));
  return hits[0];
}

async function observe(h: Host) {
  const r = await h.run();
  const msgs = await h.inFlight();
  const report = (w: string) => {
    const m = find(msgs, (x) => x.from === w && x.action === 'Report');
    return m ? (m.data.outcome as string) : 'none';
  };
  return {
    runStatus: r.status, task0: r.task0, task1: r.task1, retried0: r.retried0, retried1: r.retried1,
    w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status,
    assign0: !!find(msgs, (m) => m.to === 'worker0' && m.action === 'Assign'),
    assign1: !!find(msgs, (m) => m.to === 'worker1' && m.action === 'Assign'),
    // Aborts carry no data, so two to one worker are interchangeable: count them.
    abort0: msgs.filter((m) => m.to === 'worker0' && m.action === 'Abort').length,
    abort1: msgs.filter((m) => m.to === 'worker1' && m.action === 'Abort').length,
    report0: report('worker0'), report1: report('worker1'),
  };
}

async function apply(h: Host, action: string, arg: string | number | undefined) {
  const msgs = await h.inFlight();
  const deliver = async (m: Message | undefined) => h.deliver(m ? m.id : 'no-such-message');
  const worker = String(arg);
  switch (action) {
    case 'TASK_TIMEOUT': return h.taskTimeout(arg as number);
    case 'START': return h.start();
    case 'CANCEL': return h.cancel();
    case 'WORK_DONE': return h.workDone(worker);
    case 'WORK_FAILED': return h.workFailed(worker);
    case 'DELIVER_ASSIGN': return deliver(find(msgs, (m) => m.to === worker && m.action === 'Assign'));
    case 'DELIVER_ABORT': return deliver(msgs.find((m) => m.to === worker && m.action === 'Abort'));
    case 'DELIVER_REPORT': return deliver(find(msgs, (m) => m.from === worker && m.action === 'Report'));
  }
}

type Step = [string, (string | number)?];

async function runScenario(name: string, steps: Step[]) {
  const h = await createHost();
  const lines: string[] = [];
