import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const view = async (h: Host) => {
  const r = await h.run();
  return { status: r.status, task0: r.task0, task1: r.task1 };
};

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await view(h), { status: 'running', task0: 'assigned', task1: 'assigned' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliver(r.id);
  assert.deepEqual(await view(h), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('first failure while running is retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker1');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

test('second failure is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true });
  assert.deepEqual(await h.inFlight(), []);
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'failed', task0: 'completed', task1: 'failed' });
  assert.equal((await h.cancel()).ok, false);
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0'); // report in flight
  await h.cancel(); // aborts both, task0 still assigned
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('cancel during a retry aborts the retried task', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'running', task0: 'assigned', task1: 'completed' });
  await h.cancel();
  assert.deepEqual((await h.inFlight()).map((m) => [m.to, m.action]), [['worker0', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'completed', retried0: true, retried1: false });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  assert.equal((await h.cancel()).ok, false);
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await view(h), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('abort racing a completion is ignored by the idle worker', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0'); // report in flight
  await h.cancel(); // aborts both
  const abort0 = (await h.inFlight()).find((m) => m.to === 'worker0' && m.action === 'Abort')!;
  await h.deliver(abort0.id);
  assert.equal((await h.inFlight()).filter((m) => m.from === 'worker0').length, 1);
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('timeout records a final failure and aborts the worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false); // not started
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  assert.deepEqual((await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  assert.equal((await h.taskTimeout(0)).ok, false); // no longer assigned
  await h.deliverAll(); // worker0 stops, its cancelled report is ignored
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await view(h), { status: 'running', task0: 'failed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'failed', task0: 'failed', task1: 'completed' });
  assert.equal((await h.taskTimeout(1)).ok, false); // terminal
});

test('late report after timeout is ignored', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1'); // completed report in flight
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'running', task0: 'assigned', task1: 'failed' });
  await h.workFailed('worker0');
  await h.deliverAll(); // retried
  await h.taskTimeout(0);
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'failed', retried0: true, retried1: false });
});

test('timeout while cancelling, with two aborts in flight', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1');
  await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.inFlight()).filter((m) => m.to === 'worker0' && m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'failed', task0: 'failed', task1: 'completed' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('unknown worker refused', async () => {
  const h = await createHost();
  assert.equal((await h.workDone('x')).ok, false);
  assert.equal((await h.workFailed('x')).ok, false);
});

