import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const view = async (h: Host) => {
  const r = await h.run();
  return { status: r.status, task0: r.task0, task1: r.task1 };
};

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await view(h), { status: 'running', task0: 'assigned', task1: 'assigned' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliver(r.id);
  assert.deepEqual(await view(h), { status: 'running', task0: 'completed', task1: 'assigned' });
  assert.equal((await h.run()).processed, 2);
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false, processed: 3 });
});

test('workDone refuses items other than 1 or 2', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  for (const items of [0, 3, -1, 1.5, NaN, '1' as unknown as number]) {
    const out = await h.workDone('worker0', items);
    assert.equal(out.ok, false);
  }
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.inFlight(), []);
});

test('failed and cancelled reports carry 0 items', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.deepEqual((await h.inFlight())[0].data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliverAll();
  await h.cancel();
  await h.deliverAll(); // both busy: two cancelled reports
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', retried0: true, retried1: false, processed: 0 });
});

test('first failure while running is retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true, processed: 0 });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker1', 2);
  await h.workDone('worker0', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true, processed: 4 });
});

test('second failure is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true, processed: 0 });
  assert.deepEqual(await h.inFlight(), []);
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await view(h), { status: 'failed', task0: 'completed', task1: 'failed' });
  assert.equal((await h.run()).processed, 1);
  assert.equal((await h.cancel()).ok, false);
