'use strict';

// SAM v2 strict-profile specification of src/core.ts + the host's message
// queue (src/host.impl.ts). Each in-flight message kind is a state key: at most
// one Assign and one Report per worker can be in flight; Aborts (cancel and a
// timeout can both send one) are counted.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = {
  runStatus: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false, w0: 'idle', w1: 'idle',
  assign0: false, assign1: false, abort0: 0, abort1: 0,
  report0: 'none', report1: 'none',
  // processed: the run's total; itemsN: the items field of workerN's in-flight Report
  processed: 0, items0: 0, items1: 0,
};

const ALL = Object.keys(INITIAL_STATE);
const WORKER = { type: 'object', properties: { worker: { type: 'string' } }, required: ['worker'] };
const WORKER_DOMAIN = [{ worker: 'worker0' }, { worker: 'worker1' }];
const idx = (worker) => (worker === 'worker0' ? 0 : worker === 'worker1' ? 1 : null);
const others = (...written) => ALL.filter((k) => !written.includes(k));
const reported = (t) => t === 'completed' || t === 'failed' || t === 'cancelled';

// Record task i's final outcome and recompute the run's status.
const record = (model, next, i, outcome) => {
  const t = [model.task0, model.task1];
  t[i] = outcome;
  next['task' + i] = outcome;
  const both = reported(t[0]) && reported(t[1]);
  if (t[0] === 'completed' && t[1] === 'completed') next.runStatus = 'completed';
  else if (both && t.includes('failed')) next.runStatus = 'failed';
  else if (both) next.runStatus = 'cancelled';
  else next.runStatus = model.runStatus;
};

const finish = (outcome) => (model) => (proposal, { reject, next, unchanged }) => {
  const i = idx(proposal.worker);
  if (i === null) return reject('unknown-worker');
  const items = outcome === 'completed' ? proposal.items : 0;
  // items-1-or-2
  if (outcome === 'completed' && items !== 1 && items !== 2) return reject('items-not-1-or-2');
  if (model['w' + i] !== 'busy') return reject('worker-not-busy');
  next['w' + i] = 'idle';
  next['report' + i] = outcome;
  next['items' + i] = items;
  unchanged(...others('w' + i, 'report' + i, 'items' + i));
};

const WORK_DONE_SCHEMA = { type: 'object', properties: { worker: { type: 'string' }, items: { type: 'number' } }, required: ['worker', 'items'] };
const WORK_DONE_DOMAIN = WORKER_DOMAIN.flatMap((d) => [0, 1, 2, 3].map((items) => ({ ...d, items })));

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      runStatus: { type: 'string' }, task0: { type: 'string' }, task1: { type: 'string' },
      retried0: { type: 'boolean' }, retried1: { type: 'boolean' },
      w0: { type: 'string' }, w1: { type: 'string' },
      assign0: { type: 'boolean' }, assign1: { type: 'boolean' },
      abort0: { type: 'number' }, abort1: { type: 'number' },
      report0: { type: 'string' }, report1: { type: 'string' },
      processed: { type: 'number' }, items0: { type: 'number' }, items1: { type: 'number' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: WORK_DONE_SCHEMA, domain: WORK_DONE_DOMAIN },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: WORKER, domain: WORKER_DOMAIN },
      DELIVER_ASSIGN: { action: (data = {}) => ({ ...data }), schema: WORKER, domain: WORKER_DOMAIN },
      DELIVER_ABORT: { action: (data = {}) => ({ ...data }), schema: WORKER, domain: WORKER_DOMAIN },
      TASK_TIMEOUT: { action: (data = {}) => ({ ...data }), schema: { type: 'object', properties: { task: { type: 'number' } }, required: ['task'] }, domain: [{ task: 0 }, { task: 1 }, { task: 2 }] },
      DELIVER_REPORT: { action: (data = {}) => ({ ...data }), schema: WORKER, domain: WORKER_DOMAIN },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.runStatus !== 'idle') return reject('run-already-started');
        next.runStatus = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.assign0 = true;
        next.assign1 = true;
        unchanged(...others('runStatus', 'task0', 'task1', 'assign0', 'assign1'));
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.runStatus !== 'running') return reject('run-not-running');
        next.runStatus = 'cancelling';
        // abort-only-assigned
        next.abort0 = model.task0 === 'assigned' ? model.abort0 + 1 : model.abort0;
        next.abort1 = model.task1 === 'assigned' ? model.abort1 + 1 : model.abort1;
        unchanged(...others('runStatus', 'abort0', 'abort1'));
      },
      WORK_DONE: finish('completed'),
      WORK_FAILED: finish('failed'),
      DELIVER_ASSIGN: (model) => (proposal, { reject, next, unchanged }) => {
        const i = idx(proposal.worker);
        if (i === null) return reject('unknown-worker');
        if (!model['assign' + i]) return reject('no-assign-in-flight');
        next['assign' + i] = false;
        // assign-busy-ignored
        next['w' + i] = 'busy';
        unchanged(...others('assign' + i, 'w' + i));
      },
