  { name: 'at-most-two-aborts', pred: (s) => s.abort0 <= 2 && s.abort1 <= 2 },
  { name: 'cancelled-task-only-after-cancel',
    pred: (s) => !tasks(s).includes('cancelled') || (s.runStatus !== 'running' && s.runStatus !== 'idle') },
  // A task recorded from its worker's report has no further report pending
  // (a timed-out task may still have a late report in flight).
  { name: 'a-task-reports-once-0', pred: (s) => !(s.task0 === 'completed' || s.task0 === 'cancelled') || s.report0 === 'none' },
  { name: 'a-task-reports-once-1', pred: (s) => !(s.task1 === 'completed' || s.task1 === 'cancelled') || s.report1 === 'none' },
  { name: 'busy-worker-has-not-reported-0', pred: (s) => s.w0 !== 'busy' || s.report0 === 'none' },
  { name: 'busy-worker-has-not-reported-1', pred: (s) => s.w1 !== 'busy' || s.report1 === 'none' },
  { name: 'busy-worker-task-was-started-0', pred: (s) => s.w0 !== 'busy' || s.task0 !== 'idle' },
  { name: 'busy-worker-task-was-started-1', pred: (s) => s.w1 !== 'busy' || s.task1 !== 'idle' },
  { name: 'processed-is-1-or-2-per-completed-task',
    pred: (s) => {
      const n = tasks(s).filter((t) => t === 'completed').length;
      return s.processed >= n && s.processed <= 2 * n;
    } },
  { name: 'report-items-match-outcome',
    pred: (s) => ['0', '1'].every((i) => s['report' + i] === 'completed'
      ? s['items' + i] === 1 || s['items' + i] === 2
      : s['items' + i] === 0) },
  { name: 'retried-only-after-start',
    pred: (s) => s.runStatus !== 'idle' || (!s.retried0 && !s.retried1) },
];

const W = (d) => (d.worker === 'worker0' ? '0' : '1');

export const transitionInvariants = [
  { name: 'retried-is-permanent',
    pred: (pre, a, d, post) => (!pre.retried0 || post.retried0) && (!pre.retried1 || post.retried1) },
  { name: 'retry-only-on-report',
    pred: (pre, a, d, post) => a === 'DELIVER_REPORT' || (pre.retried0 === post.retried0 && pre.retried1 === post.retried1) },
  { name: 'first-failure-while-running-is-retried',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER_REPORT') return true;
      const i = W(d);
      if (!(pre['report' + i] === 'failed' && pre.runStatus === 'running' && pre['task' + i] === 'assigned' && !pre['retried' + i])) return true;
      return post['task' + i] === 'assigned' && post['retried' + i] && post['assign' + i] && post.runStatus === pre.runStatus;
    } },
  { name: 'failure-recorded-when-retried-or-cancelling',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER_REPORT') return true;
      const i = W(d);
      if (!(pre['report' + i] === 'failed' && pre['task' + i] === 'assigned' &&
        (pre['retried' + i] || pre.runStatus === 'cancelling'))) return true;
      return post['task' + i] === 'failed' && post['retried' + i] === pre['retried' + i];
    } },
  { name: 'terminal-run-never-changes-status',
    pred: (pre, a, d, post) => !terminal(pre.runStatus) || post.runStatus === pre.runStatus },
  { name: 'reported-task-never-changes',
    pred: (pre, a, d, post) => (!reported(pre.task0) || post.task0 === pre.task0) && (!reported(pre.task1) || post.task1 === pre.task1) },
  { name: 'cancel-aborts-only-work-in-progress',
    pred: (pre, a, d, post) => a !== 'CANCEL' ||
      ((post.abort0 === pre.abort0 || pre.task0 === 'assigned') && (post.abort1 === pre.abort1 || pre.task1 === 'assigned')) },
  { name: 'cancel-aborts-all-work-in-progress',
    pred: (pre, a, d, post) => a !== 'CANCEL' || pre.runStatus !== 'running' ||
      ((pre.task0 !== 'assigned' || post.abort0 > pre.abort0) && (pre.task1 !== 'assigned' || post.abort1 > pre.abort1)) },
  { name: 'processed-grows-only-by-a-recorded-completion',
    pred: (pre, a, d, post) => {
      if (post.processed === pre.processed) return true;
      if (a !== 'DELIVER_REPORT') return false;
      const i = W(d);
      return pre['task' + i] === 'assigned' && post['task' + i] === 'completed' &&
        post.processed === pre.processed + pre['items' + i];
    } },
  { name: 'recorded-completion-adds-its-items',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER_REPORT') return true;
      const i = W(d);
      if (!(pre['task' + i] === 'assigned' && post['task' + i] === 'completed')) return true;
      return post.processed === pre.processed + pre['items' + i];
    } },
  { name: 'timeout-is-a-final-failure-and-aborts',
    pred: (pre, a, d, post) => {
      if (a !== 'TASK_TIMEOUT' || JSON.stringify(pre) === JSON.stringify(post)) return true;
      const i = d.task === 0 ? '0' : '1';
      return post['task' + i] === 'failed' && post['retried' + i] === pre['retried' + i] &&
        post['abort' + i] === pre['abort' + i] + 1 && post['assign' + i] === pre['assign' + i];
    } },
  { name: 'late-report-ignored',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER_REPORT') return true;
      const i = W(d);
      if (pre['report' + i] === 'none' || pre['task' + i] === 'assigned') return true;
      return post.runStatus === pre.runStatus && post.task0 === pre.task0 && post.task1 === pre.task1 &&
        post.retried0 === pre.retried0 && post.retried1 === pre.retried1 && post.assign0 === pre.assign0 && post.assign1 === pre.assign1;
    } },
  { name: 'abort-never-stops-idle-worker',
    pred: (pre, a, d, post) => a !== 'DELIVER_ABORT' || pre[d.worker === 'worker0' ? 'w0' : 'w1'] !== 'idle' ||
      post[d.worker === 'worker0' ? 'report0' : 'report1'] === pre[d.worker === 'worker0' ? 'report0' : 'report1'] },
  { name: 'refused-command-changes-nothing',
    pred: (pre, a, d, post) => {
      const cmd = ['START', 'CANCEL', 'WORK_DONE', 'WORK_FAILED', 'TASK_TIMEOUT'].includes(a);
      if (!cmd) return true;
      const same = JSON.stringify(pre) === JSON.stringify(post);
      const allowed = a === 'START' ? pre.runStatus === 'idle'
        : a === 'CANCEL' ? pre.runStatus === 'running'
        : a === 'TASK_TIMEOUT' ? (d.task === 0 || d.task === 1) &&
          (pre.runStatus === 'running' || pre.runStatus === 'cancelling') && pre['task' + d.task] === 'assigned'
        : pre[d.worker === 'worker0' ? 'w0' : 'w1'] === 'busy';
      return allowed ? !same : same;
    } },
];

